//! Numeric fixtures (not source) generated by tools/perf-upstream --motion-fixtures.
//! Harmonica 0ff76e405449b47bd60f1df4820d880081692d3c; 100 fixed 16ms steps.
use matea_motion::{Motion, Point3, Projectile, Spring, Vector3};
use std::time::Duration;
#[test]
fn reference_trajectories_across_frequencies_and_damping() {
    for line in include_str!("harmonica-motion.csv").lines() {
        let values = line
            .split(',')
            .map(|v| v.parse::<f64>().unwrap())
            .collect::<Vec<_>>();
        let spring = Spring::new(Duration::from_millis(16), values[1], values[0]).unwrap();
        let mut state = Motion {
            position: 2.0,
            velocity: 0.5,
        };
        for _ in 0..100 {
            state = spring.step(state, 1.0).unwrap();
        }
        for (actual, expected) in [(state.position, values[2]), (state.velocity, values[3])] {
            assert!(
                (actual - expected).abs() < 1e-6,
                "{line}: {actual} != {expected}"
            );
        }
    }
}
#[test]
fn reference_projectiles_cover_xyz_gravity_zero_steps_and_nanosecond_periods() {
    for line in include_str!("harmonica-projectiles.csv").lines() {
        let cells: Vec<_> = line.split(',').collect();
        let numbers: Vec<f64> = cells[2..].iter().map(|n| n.parse().unwrap()).collect();
        let a = Vector3 {
            x: numbers[0],
            y: numbers[1],
            z: numbers[2],
        };
        let mut checked = Projectile::new(
            Duration::from_nanos(cells[0].parse().unwrap()),
            Point3 {
                x: 1.0,
                y: 10.0,
                z: -2.0,
            },
            Vector3 {
                x: 2.0,
                y: -3.0,
                z: 4.0,
            },
            a,
        )
        .unwrap();
        let mut raw = checked;
        for _ in 0..cells[1].parse::<usize>().unwrap() {
            checked.step().unwrap();
            raw = raw.sample();
        }
        for projectile in [checked, raw] {
            let (p, v) = (projectile.position(), projectile.velocity());
            for (actual, expected) in [p.x, p.y, p.z, v.x, v.y, v.z]
                .into_iter()
                .zip(&numbers[3..])
            {
                assert!(
                    (actual - expected).abs() <= 1e-12 * expected.abs().max(1.0),
                    "{line}: {actual} != {expected}"
                );
            }
            assert_eq!(projectile.acceleration(), a);
        }
    }
}
